'use strict';
// T24 Kanto route UI audit across all 13 real Phaser campaign scenes.
// Fixtures prepare stage and trainer counters ONLY to select screens;
// no victory, progress, badges or save content is generated by test actions.
const assert=require('node:assert/strict');
const fs=require('node:fs'),fsp=require('node:fs/promises'),path=require('node:path'),http=require('node:http');
const {chromium}=require('playwright-core');
const root=path.resolve(process.env.PREVIEW_ROOT||'_site');
const mime={'.html':'text/html','.js':'text/javascript','.json':'application/json','.css':'text/css',
 '.png':'image/png','.webp':'image/webp','.jpg':'image/jpeg','.svg':'image/svg+xml'};
const server=http.createServer(async(req,res)=>{
 const u=new URL(req.url||'/','http://127.0.0.1');
 const name=path.resolve(root,'.'+(u.pathname.endsWith('/')?u.pathname+'index.html':u.pathname));
 if(!name.startsWith(root+path.sep)){res.writeHead(403);return res.end('forbidden')}
 try{const bytes=await fsp.readFile(name);res.writeHead(200,
  {'content-type':mime[path.extname(name)]||'application/octet-stream'});res.end(bytes)}
 catch{res.writeHead(404);res.end('missing')}
});
(async()=>{
 fs.mkdirSync('test-evidence',{recursive:true});
 await new Promise(ok=>server.listen(4487,'127.0.0.1',ok));
 const browser=await chromium.launch({executablePath:process.env.CHROME_BIN||'/usr/bin/google-chrome',
  headless:true,args:['--no-sandbox','--disable-dev-shm-usage',
   '--enable-unsafe-swiftshader','--use-gl=angle','--use-angle=swiftshader']});
 let page;
 const report={scope:'T24 all Kanto native Phaser battle-path stages, mobile paging and locked gates',
 method:'prepared stage/trainer UI fixtures; no natural trainer victories, badges, KO, XP or money',
 stages:[],pages:[],locked:null,errors:[]};
 try{
  page=await browser.newPage({viewport:{width:854,height:480},isMobile:true,hasTouch:true});
  const errors=[];page.on('pageerror',x=>errors.push(String(x)));
  await page.goto('http://127.0.0.1:4487/arena2d/?original=1',
   {waitUntil:'domcontentloaded'});
  await page.waitForFunction(()=>window.__pt2Game?.scene.isActive('titulo'),null,{timeout:60000});
  await page.evaluate(async()=>{
   const src=[...document.scripts].find(s=>s.src?.includes('/main.js')).src;
   const core=window.t24Core=await import(new URL('./torre2/campaign-core.js',src));
   core.saveCampaign(core.createCampaign('bulbasaur'));
   window.__pt2Game.scene.getScene('titulo').scene.start('campanha');
  });
  await page.waitForFunction(()=>window.__pt2Game.scene.isActive('campanha')&&
   !!window.__pt2Game.scene.getScene('campanha').__torre2BattlePath,
   null,{timeout:60000});
  const tap=async(x,y)=>{
   const pos=await page.evaluate(([x,y])=>{
    const canvas=document.querySelector('#juego canvas')||document.querySelector('canvas');
    if(!canvas)throw Error('Native Phaser canvas missing');
    const rect=canvas.getBoundingClientRect();
    return {x:rect.left+x*rect.width/640,y:rect.top+y*rect.height/360};
   },[x,y]);
   assert.ok(pos.x>=0&&pos.x<=854&&pos.y>=0&&pos.y<=480,
    'T24 route touch outside mobile viewport');
   await page.touchscreen.tap(pos.x,pos.y);
  };
  const snapshot=async()=>page.evaluate(()=>{
   const s=window.t24Core.readCampaign();
   return JSON.stringify({stage:s.stage,trainer:s.trainer,wins:s.wins,
    losses:s.losses,money:s.money,badges:s.badges,
    tms:s.inventory.tms,team:s.team.map(x=>x.uid),box:s.box.map(x=>x.uid)});
  });
  const inspection=async()=>page.evaluate(()=>{
   const scene=window.__pt2Game.scene.getScene('campanha'),p=scene.__torre2BattlePath;
   if(!scene.scene.isActive()||!p)throw Error('Campaign path inactive');
   const zones=p.nodes.map(z=>({
    index:z.getData('torre2-path-node'),kind:z.getData('torre2-path-type'),
    region:z.getData('torre2-route-zone')||null,
    active:z.active,enabled:z.input?.enabled,x:z.x,y:z.y,w:z.width,h:z.height
   }));
   const actions=scene.children.list.filter(o=>o.active&&o.input?.enabled&&
    o.getData?.('torre2-path-action')!==undefined).map(o=>({
    title:o.getData('torre2-path-action'),x:o.x,y:o.y
   }));
   return {stage:p.stage,total:p.total,progress:p.progress,offset:p.offset,
    city:p.gym.city,realExterior:p.gym.realExterior,
    imageKey:p.imageKey,regions:p.regions,zones,actions,
    cta:scene.children.list.some(o=>o.active&&o.input?.enabled&&
     o.getData?.('torre2-central-cta')===true)};
  });
  for(let stage=0;stage<13;stage++){
   // This checkpoint is intentionally synthetic to inspect one route
   // without misrepresenting all preceding gyms as played.
   await page.evaluate(stage=>{
    const core=window.t24Core,scene=window.__pt2Game.scene.getScene('campanha');
    const s=core.createCampaign('bulbasaur');s.stage=stage;s.trainer=0;
    core.saveCampaign(s);scene.renderCampaign(core.readCampaign());
   },stage);
   const first=await inspection();
   const total=await page.evaluate(stage=>window.t24Core.TRAINERS_PER_GYM(stage),stage);
   assert.equal(first.stage,stage);
   assert.equal(first.total,total);
   assert.equal(first.progress,0);
   assert.equal(first.offset,0);
   assert.ok(first.cta,'Campaign battle CTA missing stage '+stage);
   assert.ok(first.imageKey.startsWith('frlg-location-'));
   assert.equal(first.zones.length,Math.min(14,total+1));
   assert.deepEqual(first.zones.map(z=>z.index),
    Array.from({length:Math.min(14,total+1)},(_,i)=>i));
   assert.equal(new Set(first.zones.map(z=>z.index)).size,first.zones.length);
   for(const z of first.zones){
    assert.ok(z.active&&z.enabled,'Native checkpoint disabled '+stage+'/'+z.index);
    assert.ok(z.x>=0&&z.x<=640&&z.y>=0&&z.y<=360,
     'Native checkpoint out of bounds '+stage+'/'+z.index);
    assert.ok(z.w>0&&z.h>0);
   }
   if(total===0)assert.equal(first.zones[0].kind,'leader');
   const proof={stage,total,first:first.zones.length,city:first.city,
    backdrop:first.realExterior,visitedPages:[0],lastIndex:total};
   const originalSave=await snapshot();
   if(stage===1){
    const z=first.zones.find(x=>x.index===1);
    assert.ok(z&&z.kind!=='leader');
    await tap(z.x,z.y);
    const afterLocked=await snapshot();
    assert.equal(afterLocked,originalSave,'Locked route node mutated campaign save');
    assert.equal(await page.evaluate(()=>window.__pt2Game.scene.isActive('combate')),
     false,'Locked route node started unauthorized combat');
    report.locked={stage,index:1,saveUnchanged:true,noBattle:true};
    await page.screenshot({path:'test-evidence/t24-cerulean-locked-mobile.png'});
   }
   let current=first;
   while(current.offset+current.zones.length<total+1){
    const next=current.actions.find(x=>x.title==='▶');
    assert.ok(next,'Missing next page action stage '+stage+' at offset '+current.offset);
    await tap(next.x,next.y);
    const later=await inspection();
    assert.ok(later.offset>current.offset,'Next page did not advance');
    assert.equal(later.offset,current.offset+13,'Route paging shifted wrong count');
    assert.equal(later.zones[0].index,later.offset);
    assert.ok(later.zones.every(z=>z.index>=later.offset&&z.index<=total),
     'Future route rendered inaccessible global checkpoint');
    proof.visitedPages.push(later.offset);
    current=later;
   }
   assert.ok(current.zones.some(z=>z.index===total),'Leader/League final node missing');
   assert.equal(current.zones.find(z=>z.index===total).kind,'leader');
   if(proof.visitedPages.length>1){
    while(current.offset>0){
     const back=current.actions.find(x=>x.title==='◀');
     assert.ok(back,'Missing back page action stage '+stage);
     await tap(back.x,back.y);
     const prev=await inspection();
     assert.equal(prev.offset,current.offset-13);
     current=prev;
    }
    assert.equal(current.offset,0);
   }
   assert.equal(await snapshot(),originalSave,
    'Merely navigating path UI changed money, badges, XP or saved progress');
   // At the exact boss checkpoint, map automatically opens the last page.
   await page.evaluate(([stage,total])=>{
    const core=window.t24Core,scene=window.__pt2Game.scene.getScene('campanha');
    const state=core.readCampaign();
    state.stage=stage;state.trainer=total;
    core.saveCampaign(state);scene.renderCampaign(core.readCampaign());
   },[stage,total]);
   const bossPage=await inspection();
   assert.equal(bossPage.progress,total);
   assert.ok(bossPage.zones.some(z=>z.index===total&&z.kind==='leader'));
   // Index 13 is already visible on page zero (14 visible spots).
   const expectedBossPage=total<=13?0:Math.floor((total-1)/13)*13;
   assert.equal(bossPage.offset,expectedBossPage,
    'Completed trainer must auto-focus its visible map page');
   proof.bossPage=bossPage.offset;
   report.stages.push(proof);
  }
  assert.equal(report.stages.length,13);
  assert.ok(report.stages.some(s=>s.visitedPages.length>=3),
   'Long route never exercised more than two pages');
  assert.deepEqual(errors,[],'Phaser exceptions while navigating native Kanto route');
  report.errors=errors;
  await page.screenshot({path:'test-evidence/t24-kanto-final-route-mobile.png'});
  fs.writeFileSync('test-evidence/t24-kanto-13-stage-mobile-routes.json',
   JSON.stringify(report,null,2));
  console.log('T24 13 KANTO ROUTE STAGES AND MOBILE PAGES PASS',JSON.stringify({
   stages:report.stages.length,pages:report.stages.reduce((n,s)=>n+s.visitedPages.length,0),
   longest:Math.max(...report.stages.map(s=>s.visitedPages.length)),
   locked:report.locked?.saveUnchanged
  }));
 }finally{if(page&&!page.isClosed())await page.close();await browser.close();server.close()}
})().catch(e=>{console.error(e);process.exitCode=1;server.close()});
